import {sources,strategies,levels,samplePlan as baseSamplePlan} from './data.js';
import {simplified} from './locale.js';
import {curricula,getSubjects,getStages,stageLabel} from './classroom.js';
import {normalizeRecord,appendFeedback,feedbackContext,validPreset,teachingSetup,normalizeSettings,validProfile,mergeSettings,reuseActivity} from './workspace.js';
import {readWord} from './word-import.js';
for(const item of [...strategies,...sources])item['zh-CN']=simplified(item.zh);
levels['zh-CN']=simplified(levels.zh);
function samplePlan(d,l){const base=baseSamplePlan(d,l==='zh-CN'?'zh':l);const p=l==='zh-CN'?{...simplified(base),goal:d.goal}:base;return {...p,knowledgePath:l==='en'?['Recall relevant prior learning','Try an example and connect ideas','Apply independently and check understanding']:l==='zh-CN'?['回顾相关已有知识','通过例子连接概念','独立应用并检查理解']:['重溫相關已有知識','透過例子連結概念','獨立應用並檢查理解']};}
const $=s=>document.querySelector(s);
function initialLanguage(){try{const pref=(localStorage.getItem('teachwithwhy-ui-language')||localStorage.getItem('etc-ui-language'));if(['zh','en','zh-CN'].includes(pref))return pref;}catch{}return location.pathname.startsWith('/en')?'en':location.pathname.startsWith('/zh-CN')?'zh-CN':'zh';}
let lang=initialLanguage(),en=lang==='en';
const t=(zh,english,cn)=>en?english:lang==='zh-CN'?(cn??simplified(zh)):zh;
if(['/zh','/zh/','/en','/en/','/zh-CN','/zh-CN/'].includes(location.pathname))history.replaceState(null,'','/'+location.search+location.hash);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function translate_names(){return {home:t('設計活動','Design an activity'),create:t('設計活動','Design an activity'),compare:t('比較策略','Compare strategies'),plan:t('編輯活動','Edit activity'),reflect:t('課後回顧','Classroom reflection'),history:t('已儲存活動','Saved activities'),library:t('研究與策略庫','Evidence library'),guide:t('使用說明','User guide'),about:t('關於與連線狀態','About & connection')};}
let names=translate_names();
const subjectOptions=()=>getSubjects(draft.curriculum,draft.level,lang);
function translate_exampleProblems(){return t(['課堂提問總是由少數學生回答，其他學生很少表達想法。','小組討論由一兩人包辦，其他同學等着抄答案。','學生只給簡短答案，很少解釋原因或回應同學。'],['Only a few pupils answer questions while others rarely express their ideas.','One or two pupils do the group task while others wait to copy the answer.','Pupils give short answers without explaining reasons or responding to peers.']);}
let exampleProblems=translate_exampleProblems();
function translate_exampleGoals(){return t(['讓更多學生先形成自己的想法，並用不同方式參與。','讓每人提出一項貢獻，並能解釋小組答案怎樣形成。','讓學生用理由支持想法，並嘗試回應同學。'],['Help more pupils prepare their own ideas and participate in different ways.','Each pupil contributes and can explain how the shared response was formed.','Pupils support an idea with a reason and respond to a peer.']);}
let exampleGoals=translate_exampleGoals();
let teachingSettings;try{teachingSettings=normalizeSettings(JSON.parse(localStorage.getItem('teachwithwhy-teaching-settings-v1')||'{}'));}catch{teachingSettings=normalizeSettings();}
let profileName='',planEditing=false;
const blank=()=>({level:'upper',curriculum:'hk',curriculumNote:'',subject:getSubjects('hk','upper',lang)[0],customSubject:'',customPrompt:'',documentContext:'',documentName:'',feedbackIds:[],students:30,minutes:12,topic:'',problem:'',goal:'',fromScenario:false,constraints:['seats'],strategy:'auto',textbook:'',classContext:'',knowledgePoints:'',...localizedSetup(teachingSettings.lastSetup),consent:false});
function load(){try{let data=JSON.parse(localStorage.getItem('teachwithwhy-records-v2')||localStorage.getItem('evidence-classroom-v2')||localStorage.getItem('evidence-classroom-v1')||'[]');return Array.isArray(data)?data.filter(r=>r?.id&&r.draft&&r.plan).map(r=>normalizeRecord({...r,plan:{origin:'template',...r.plan}})):[];}catch{return [];}}
let presets=[];try{const saved=JSON.parse(localStorage.getItem('teachwithwhy-prompts-v1')||'[]');presets=Array.isArray(saved)?saved.filter(validPreset).slice(0,30):[];}catch{}
let presetTitle='',presetEditor=false,onlyFavorites=false,documentImport={text:'',name:'',suggestion:null,notes:'',consent:false,error:''};
let records=load(),draft=blank(),plan=null,activeId=null,view='home',busy=false,api={configured:false,provider:'deepseek',model:'deepseek-flash',liveSearch:true},apiChecked=false,toastTimer;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function persist(){try{localStorage.setItem('teachwithwhy-records-v2',JSON.stringify(records));return true;}catch{toast(t('無法儲存，請先下載備份。','Storage unavailable. Please download a backup.'));return false;}}
function b(label,attrs='',variant=''){return `<button class="button ${variant}" ${attrs}>${label}</button>`;}
function heading(eyebrow,title,sub,extra=''){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtext">${sub}</p></div>${extra}</div>`;}
function shell(){document.documentElement.lang=en?'en':lang==='zh-CN'?'zh-Hans':'zh-Hant-HK';document.title=t('教得有據 · TeachWithWhy','TeachWithWhy · Teacher Workspace');$('#app').innerHTML=`<a class="skip" href="#main">${t('跳至主要內容','Skip to content')}</a><div class="mobile-helpbar" aria-label="${t('手機使用支援','Mobile help','手机使用帮助')}"><button type="button" class="mobile-guide-button" data-nav="guide">? ${t('使用說明','User guide','使用说明')}</button><button type="button" class="mobile-install-button" data-action="install-guide">＋ ${t('加至主畫面','Add to Home Screen','添加到主屏幕')}</button></div><aside class="sidebar"><a href="/" class="brand"><span class="brand-symbol">教<span>↗</span></span><span>${t('教得有據','TeachWithWhy')}<small>${t('TEACHWITHWHY','RESEARCH · TRY · REFLECT')}</small></span></a><div class="workspace-label">${t('教師工作區','TEACHER WORKSPACE')}</div><nav aria-label="${t('主要選單','Main navigation')}">${[['home','＋'],['history','◷']].map(([id,icon])=>`<button data-nav="${id}"><span class="nav-icon">${icon}</span>${names[id]}${id==='history'?'<span id="saved-count" class="nav-count"></span>':''}</button>`).join('')}</nav><div class="sidebar-note"><span class="leaf">✳</span><strong>${t('讓研究走進課堂','Make evidence practical')}</strong><p>${t('每一次有依據的小嘗試，<br>都是教學改進的起點。','Small, informed trials.<br>Room to reflect and refine.')}</p></div><button data-nav="about" class="workspace-user"><span class="avatar">T</span><span>${t('我的教師工作區','My teacher workspace')}<small>${t('紀錄儲存於此瀏覽器','Records saved in this browser')}</small></span><span>↗</span></button></aside><div class="app-shell"><header class="topbar"><div id="breadcrumb"></div><div class="topbar-right"><span id="ai-status" class="prototype-badge"></span><label class="language-select"><span class="sr-only">${t('介面語言','Interface language')}</span><select id="ui-language" aria-label="${t('介面語言','Interface language')}">${[['zh','香港繁體'],['zh-CN','简体中文'],['en','English']].map(([value,label])=>`<option value="${value}" ${lang===value?'selected':''}>${label}</option>`).join('')}</select></label><button class="text-button" data-nav="guide">${t('使用說明','User guide')} ↗</button></div></header><main id="main" tabindex="-1"></main><footer><span>${t('支援香港、內地及國際課程的中小學教師','For primary & secondary teachers across Hong Kong, mainland and international curricula')}</span><span>${t('研究有依據，教學有判斷。','Evidence informs. Teachers decide.')}</span></footer></div>`;$('#close-dialog').textContent=t('關閉','Close');updateStatus();}
function updateStatus(){document.querySelectorAll('[data-action="parse-document"]').forEach(button=>button.disabled=busy||!api.configured);const start=$('#generate-start');if(start){start.disabled=busy||!api.configured;start.textContent=busy?t('正在設計…','Generating…'):api.configured?t('生成課堂活動 →','Generate an activity →'):apiChecked?t('AI 暫未啟用','AI not enabled yet'):t('檢查 AI 連線…','Checking AI…');}const note=$('#generation-note');if(note&&!api.configured&&apiChecked)note.textContent=t('AI 尚未接通，可先用示範活動熟悉操作。','AI is not connected yet. Explore a sample to try the workflow.');if(!$('#ai-status'))return;$('#ai-status').innerHTML=`<i style="background:${api.configured?'#6b9366':'#aa9964'}"></i>${busy?t('正在處理…','Processing…'):api.configured?t('免費 AI · 可生成','Free AI · ready'):t('AI 尚未啟用 · 可用示例','AI not enabled · samples available')}`;}
async function checkStatus(){try{const r=await fetch('/api/status',{signal:AbortSignal.timeout(5000)});if(r.ok){const j=await r.json();if(typeof j.configured==='boolean')api=j;}}catch{}apiChecked=true;updateStatus();if(['about','guide'].includes(view))navigate(view,false);}
function navigate(v,focus=true){if(['library','compare','create'].includes(v))v='home';view=v;document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===(['create','compare','plan','reflect'].includes(v)?'home':v)));$('#breadcrumb').textContent=names[v];$('#saved-count').textContent=records.length;$('#main').innerHTML=({home:homeView,create:createView,compare:compareView,plan:planView,reflect:reflectView,history:historyView,library:libraryView,guide:guideView,about:aboutView})[v]();bindForms();updateStatus();if(focus){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}}
function steps(n){const index=n===3?2:n===2?1:0;return `<div class="wizard-steps">${[t('填寫課題','Describe'),t('修改與使用','Edit & use'),t('課後回顧（選用）','Reflect (optional)')].map((label,i)=>`${i?'<b>→</b>':''}<span class="${i===index?'current':''}">0${i+1} ${label}</span>`).join('')}</div>`;}

function homeView(){return `${heading(t('TEACHWITHWHY · 免費使用','TEACHWITHWHY · FREE TO USE'),t('下一堂，你想教甚麼？','What are you teaching next?'),t('保留你的學習目標，設計下一堂可嘗試的活動，並想清楚怎樣觀察學習。','Start with your learning goal. Plan a practical activity and a way to check learning.'))}${documentImportView()}<div class="layout-two simple-start"><form id="class-form" class="form-panel">${profileView()}${draft.reuseContext?`<div class="notice"><strong>${t('沿用並改進：','Reuse & improve: ')}${esc(draft.reuseContext.title)}</strong><p>${t('將另存為新活動，原有活動及回顧保留。可修改課題、目標及提示；下方可取消選用原有回顧。','This becomes a new activity; the original and its reflections are retained. Edit the topic, goal or prompt, and deselect feedback below if needed.')}</p></div>`:''}<details class="context-settings" ${!teachingSettings.lastSetup?'open':''}><summary>${t('班級、教材及常用設定','Class, textbook & usual settings')}</summary><div class="field-grid"><div class="field"><label for="curriculum">${t('課程類別','Curriculum context')}</label><select id="curriculum" name="curriculum">${Object.entries(curricula).map(([id,x])=>`<option value="${id}" ${draft.curriculum===id?'selected':''}>${x[lang]}</option>`).join('')}</select></div><div class="field"><label for="level">${t('學習階段','School stage')}</label><select id="level" name="level">${Object.entries(getStages(draft.curriculum,lang)).map(([key,label])=>`<option value="${key}" ${draft.level===key?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="field"><label for="curriculum-note">${t('實際年級／課綱補充（選填）','Exact year group / programme (optional)')}</label><input id="curriculum-note" name="curriculumNote" maxlength="400" value="${esc(draft.curriculumNote)}" placeholder="${t('例如：小五、七年級、IB MYP Year 2、Cambridge；以學校安排為準','For example: P5, Grade 7, IB MYP Year 2, Cambridge; follow your school’s arrangements')}"></div><p class="subtext">${t('科目選項只作常見起點，並非官方課程清單或認證；可自行填寫校本科目。','Subject options are common starting points, not an official curriculum list or accreditation. You can enter your school’s subject.')}</p><div class="field-grid"><div class="field"><label for="subject">${t('科目','Subject')}</label><select id="subject" name="subject">${subjectOptions().map(label=>`<option ${draft.subject===label?'selected':''}>${esc(label)}</option>`).join('')}${!subjectOptions().includes(draft.subject)?`<option selected>${esc(draft.subject)}</option>`:''}</select></div><div class="field"><label for="custom-subject">${t('自行填寫科目（選填，優先採用）','Custom subject (optional; takes priority)')}</label><input id="custom-subject" name="customSubject" maxlength="80" value="${esc(draft.customSubject||'')}" placeholder="${t('例如：全球視野、校本專題','For example: Global Perspectives, school-based project')}"></div></div><div class="field-grid"><div class="field"><label for="students">${t('學生人數','Number of pupils')}</label><input id="students" name="students" type="number" required min="2" max="60" value="${draft.students}"></div><div class="field"><label for="minutes">${t('活動時間（分鐘）','Activity length (minutes)')}</label><input id="minutes" name="minutes" type="number" required min="5" max="30" value="${draft.minutes}"></div></div><div class="field"><label for="textbook">${t('教材／版本（選填）','Textbook / edition (optional)')}</label><input id="textbook" name="textbook" maxlength="300" value="${esc(draft.textbook||'')}" placeholder="${t('例如：教材名稱、版本、冊次；不代表 AI 已讀取全書','Title, edition and volume; this does not give AI access to the book')}"></div><div class="field"><label for="class-context">${t('班級的一般學習需要（選填）','Usual class learning needs (optional)')}</label><textarea id="class-context" name="classContext" maxlength="1000">${esc(draft.classContext||'')}</textarea></div><p class="subtext">${t('最近使用的設定會保留在此瀏覽器。多個班級可分別儲存；請勿填寫學生個人資料。','Recent settings stay in this browser. Save separate setups for different classes; exclude pupil-identifying details.')}</p></details><div class="field"><label for="topic">${t('這一課的課題','Lesson topic')} *</label><input id="topic" name="topic" required maxlength="100" value="${esc(draft.topic)}" placeholder="${t('例如：《龜兔賽跑》人物行為與理由','For example: explaining characters’ actions in a story')}"></div><details class="context-settings"><summary>${t('補充本課的學生基礎與困難（選填）','Prior learning / difficulties for this lesson (optional)')}</summary><div class="field"><label for="problem">${t('學生已有甚麼基礎？目前遇到甚麼困難？','What can pupils already do, and where are they struggling?')}</label><textarea id="problem" name="problem" maxlength="1200">${esc(draft.problem)}</textarea><div class="quick-fill"><span>${t('快速填寫：','Try: ')}</span>${[t('多人參與','More participation'),t('小組合作','Group work'),t('講出理由','Giving reasons')].map((label,i)=>`<button type="button" class="inline-link" data-fill="${i}">${label}</button>`).join('')}</div></div></details><div class="field"><label for="goal">${t('活動後，希望學生能做到甚麼？','What should pupils be able to do afterwards?')} *</label><textarea id="goal" name="goal" required maxlength="800" placeholder="${t('請寫可觀察的學習表現，例如引用一個例子解釋看法。','Describe an observable outcome, such as using one example to explain a view.')}">${esc(draft.goal)}</textarea></div><div class="field"><label for="knowledge-points">${t('想串連的知識點（選填）','Knowledge points to connect (optional)')}</label><textarea id="knowledge-points" name="knowledgePoints" maxlength="1200" placeholder="${t('例如：同一個整體 → 等分 → 分數表示 → 等值分數；也可只寫關鍵詞','For example: same whole → equal parts → fraction notation → equivalent fractions; keywords are enough')}">${esc(draft.knowledgePoints||'')}</textarea></div><details class="context-settings"><summary>${t('教學方法及資源限制','Approach & resource constraints')}</summary><div class="field"><label for="strategy">${t('教學方法','Teaching approach')}</label><select id="strategy" name="strategy"><option value="auto" ${draft.strategy==='auto'?'selected':''}>${t('由 AI 配合課題建議','Let AI suggest an approach')}</option>${strategies.map(x=>`<option value="${x.id}" ${draft.strategy===x.id?'selected':''}>${x[lang].name}</option>`).join('')}</select></div><div class="checks">${[['seats',t('不移動座位','Keep seats in place')],['no-tech',t('不用電子裝置','No electronic devices')],['support',t('提供表達提示及句式','Include language prompts')]].map(([key,label])=>`<label><input type="checkbox" name="constraints" value="${key}" ${draft.constraints.includes(key)?'checked':''}>${label}</label>`).join('')}</div></details>${presetView()}${feedbackSelector()}${draft.documentContext?`<div class="notice">${t('已附上你確認的教案文字，生成時會一併參考。','Your reviewed document text will be included in generation.')} <button type="button" class="inline-link" data-action="clear-document">${t('移除教案文字','Remove document text')}</button></div>`:''}<div class="field consent-box"><label><input type="checkbox" name="consent" ${draft.consent?'checked':''}>${t('我確認沒有加入學生個人資料，並同意把以上內容及勾選的回顧交由網站設定的 AI 服務處理。','I confirm there are no pupil-identifying details and consent to the configured AI processing the above content and selected reflections.')}</label></div><div class="start-actions"><button id="generate-start" class="button" type="submit" ${!api.configured?'disabled':''}>${t('生成課堂活動 →','Generate an activity →')}</button><button type="button" class="text-button" data-action="sample-start">${t('先試示範活動','Explore a sample')}</button></div><p id="generation-note" class="subtext">${t('請先核對 AI 草稿，再按學生需要修改。','Review the AI draft and adapt it to your pupils.')}</p><div id="ai-error" role="alert"></div></form><aside class="start-help"><h2>${t('你會得到甚麼？','What will you get?')}</h2><ul><li>${t('知識點的銜接、每個環節的任務及學習檢查','Connections between knowledge points, stage tasks and learning checks')}</li><li>${t('學習檢查及繼續、調整或轉換方法的參考','Learning checks and guidance on keeping, adapting or changing the approach')}</li></ul><p>${t('以具體課題及學習目標為起點，先看可實行的流程。提問、設計說明及研究依據按需要展開。','Start with a concrete topic and learning goal. View the practical flow first; expand prompts, design notes and research when needed.')}</p><p>${t('收藏、自訂提示及回顧只保存在此瀏覽器，可下載備份。AI 不會在此網站自動訓練模型。','Favorites, prompts and reflections stay in this browser and can be backed up. This site does not automatically train a model.')}</p><button class="inline-link" data-nav="guide">${t('使用說明','User guide')} ↗</button></aside></div>`;}
function documentImportView(){return `<details class="document-import" ${documentImport.text||documentImport.error?'open':''}><summary>${t('已有教案？匯入 Word（.docx）','Already have a lesson plan? Import Word (.docx)')}</summary><p class="subtext">${t('先在瀏覽器讀取正文及表格文字，原檔不會上傳。核對及刪去個人資料後，才交由 AI 解析。上限 5 MB／20,000 字；不讀取圖片、批注及頁首頁尾。舊 .doc 請先另存為 .docx。','Text is extracted in your browser; the original file is not uploaded. Review and remove identifying data before AI analysis. Limit: 5 MB / 20,000 characters. Images, comments and headers/footers are excluded. Save legacy .doc as .docx first.')}</p><label class="button secondary" for="word-file">${t('選擇 Word 檔案','Choose a Word file')}</label><input id="word-file" type="file" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document" hidden><span class="file-name">${esc(documentImport.name)}</span><div class="field"><label for="document-text">${t('核對教案文字（也可直接貼上）','Review document text (or paste it here)')}</label><textarea id="document-text" maxlength="20000" rows="6">${esc(documentImport.text)}</textarea></div><label class="document-consent"><input type="checkbox" id="document-consent" ${documentImport.consent?'checked':''}>${t('我已刪去個人資料，同意把這段文字交由 AI 解析。','I have removed identifying data and consent to AI analysis of this text.')}</label><div class="start-actions"><button type="button" class="button secondary" data-action="parse-document" ${busy||!api.configured?'disabled':''}>${t('AI 解析教案','Analyse with AI')}</button><span class="subtext">${t('不會覆蓋表格；先看解析結果再套用。','Review the analysis before applying it to the form.')}</span></div><div role="alert">${esc(documentImport.error)}</div>${documentImport.suggestion?`<div class="import-review"><h3>${t('解析結果 · 請先確認','Analysis · review before applying')}</h3><dl>${Object.entries(documentImport.suggestion).filter(([,v])=>v!==null).map(([key,value])=>`<dt>${({topic:t('課題','Topic'),problem:t('學生基礎／困難','Prior learning / needs'),goal:t('學習目標','Goal'),subject:t('科目','Subject'),students:t('人數','Pupils'),minutes:t('分鐘','Minutes'),level:t('階段','Stage'),curriculum:t('課程','Curriculum'),curriculumNote:t('課綱補充','Programme details')})[key]||key}</dt><dd>${esc(key==='level'?getStages(documentImport.suggestion.curriculum||draft.curriculum,lang)[value]:key==='curriculum'?curricula[value]?.[lang]:value)}</dd>`).join('')}</dl><p>${esc(documentImport.notes)}</p><button type="button" class="button" data-action="apply-document">${t('確認並套用到表格','Confirm & apply to the form')}</button><p class="subtext">${t('會套用上列已識別的欄位並附上核對後文字；未提及的資料仍由老師補充。','Identified fields will be applied and the reviewed text attached. Fill missing context yourself.')}</p></div>`:''}</details>`;}
function presetView(){return `<section class="prompt-panel"><div class="field"><label for="custom-prompt">${t('自訂教學提示（選填）','My teaching prompt (optional)')}</label><textarea id="custom-prompt" name="customPrompt" maxlength="1500" placeholder="${t('例如：先示範一個例子，再讓每位學生獨立作答；材料只用原有簿冊。','For example: model one example before independent responses; use existing exercise books.')}">${esc(draft.customPrompt)}</textarea></div><div class="prompt-chips">${presets.map(x=>`<span class="prompt-chip"><button type="button" data-preset="${esc(x.id)}">${esc(x.title)}</button><button type="button" data-remove-preset="${esc(x.id)}" aria-label="${t('刪除提示','Delete prompt')}: ${esc(x.title)}">×</button></span>`).join('')}</div><button type="button" class="inline-link" data-action="toggle-preset">＋ ${t('把這段提示儲存為快捷按鈕','Save this prompt as a shortcut')}</button>${presetEditor?`<div class="preset-editor"><label for="preset-title">${t('按鈕名稱','Shortcut name')}</label><input id="preset-title" maxlength="60" value="${esc(presetTitle)}" placeholder="${t('例如：低準備、先示範','For example: low-prep modelling')}"><button type="button" class="button secondary" data-action="save-preset">${t('儲存提示','Save prompt')}</button></div>`:''}</section>`;}
function feedbackSelector(){const items=records.filter(r=>r.reflection?.observation).sort((a,b)=>String(b.updated).localeCompare(String(a.updated)));return `<details class="feedback-selector" ${(draft.feedbackIds||[]).length?'open':''}><summary>${t('讓 AI 參考過往回顧（選用，最多 3 份）','Let AI use past reflections (optional, up to 3)')}</summary><p class="subtext">${t('只會傳送勾選活動的目標及最新回顧摘要，以改善下一份建議；不會自動訓練模型。','Only goals and the latest reflection excerpts from selected activities are sent to inform the next suggestion; this is not automatic model training.')}</p>${items.length?items.map(r=>`<label class="feedback-option"><input type="checkbox" name="feedbackIds" value="${esc(r.id)}" ${(draft.feedbackIds||[]).includes(r.id)?'checked':''}><span><strong>${esc(r.title)}</strong><small>${esc(r.reflection.difficulty||r.reflection.next||r.reflection.observation)}</small></span></label>`).join(''):`<p>${t('儲存一次課後回顧後，就可以在這裏選用。','Save a classroom reflection to select it here.')}</p>`}</details>`;}
function createView(){return homeView();}
function capture(){if($('#profile-name'))profileName=$('#profile-name').value;if($('#preset-title'))presetTitle=$('#preset-title').value;const f=$('#class-form');if(!f)return;const d=new FormData(f);for(const k of ['curriculum','curriculumNote','level','subject','customSubject','topic','problem','goal','strategy','customPrompt','textbook','classContext','knowledgePoints'])draft[k]=String(d.get(k)||'');if(draft.customSubject.trim())draft.subject=draft.customSubject.trim();draft.feedbackIds=d.getAll('feedbackIds').slice(0,3);if($('#document-text')){documentImport.text=$('#document-text').value;documentImport.consent=$('#document-consent').checked;if(documentImport.attached)draft.documentContext=documentImport.text;}draft.students=Number(d.get('students'));draft.minutes=Number(d.get('minutes'));draft.constraints=d.getAll('constraints');draft.consent=d.has('consent');rememberSetup();}
function summary(){return `<div class="summary-bar"><span class="tag green">${esc(curricula[draft.curriculum||'hk'][lang])} · ${esc(stageLabel(draft,lang))}</span><span>${esc(draft.subject)}</span><span>· ${draft.students} ${t('人','pupils')} · ${draft.minutes} ${t('分鐘','minutes')}</span><button class="text-button" data-nav="create">${t('修改條件 ↗','Edit context ↗')}</button></div>`;}
function compareView(){return homeView();}
const errorText=code=>({AI_NOT_CONFIGURED:t('AI 暫未啟用，你仍可免費使用示範活動、編輯及儲存。','AI is not enabled yet. Samples, editing and saving are still free to use.'),CONSENT_REQUIRED:t('請返回課堂設定，確認 AI 資料傳送選項。','Return to classroom settings and confirm AI data processing consent.'),PROVIDER_AUTH:t('模型服務拒絕認證，請管理員檢查密鑰。','Model authentication failed. Ask the owner to check the key.'),PROVIDER_BALANCE:t('模型帳戶餘額不足。','The model account has insufficient credit.'),PROVIDER_RATE_LIMIT:t('模型服務繁忙，請稍後再試。','The model service is rate limited. Try again later.'),APP_RATE_LIMIT:t('已達本服務的暫時使用額度，請稍後再試。','The temporary usage limit has been reached. Try again later.'),LIVE_RETRIEVAL_UNAVAILABLE:t('暫時未能讀取研究來源，請稍後再試，或先查看示範活動。','Research pages could not be retrieved. Try again later or explore a sample.'),PROVIDER_UNREACHABLE:t('無法連上模型或檢索服務，尚未產生 AI 方案。','The model or search service could not be reached. No AI plan was generated.'),INVALID_MODEL_OUTPUT:t('AI 回傳格式不完整，沒有用模板冒充結果。請重新嘗試。','The AI output was incomplete. It has not been replaced with a template. Please try again.'),INVALID_CITATION:t('AI 引用了無法核對的來源，這次結果未採用。','The AI cited an unverified source. This result was not accepted.'),NETWORK_ERROR:t('連線中斷或逾時，請稍後重試。','The connection failed or timed out. Please try again.'),INVALID_INPUT:t('請檢查人數、時間及必填內容。','Check the class size, activity length and required fields.')})[code]||t('AI 服務未能完成，請稍後重試。','The AI service could not complete the request. Please try again.');
async function aiRequest(action,extra={}){if(!draft.consent)throw new Error('CONSENT_REQUIRED');const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,draft:action==='reflect'?{...draft,documentContext:''}:draft,lang,consent:true,...(action==='plan'?{feedbackContext:feedbackContext(records,draft.feedbackIds||[])}:{}),...extra}),signal:AbortSignal.timeout(115000)});let data;try{data=await r.json();}catch{throw new Error('AI_NOT_CONFIGURED');}if(!r.ok)throw new Error(data.error||'NETWORK_ERROR');return data;}
async function generate(id){draft.strategy=id;if(!api.configured){toast(errorText('AI_NOT_CONFIGURED'));return;}busy=true;updateStatus();document.querySelectorAll('[data-ai],[data-sample]').forEach(x=>x.disabled=true);try{const result=await aiRequest('plan');plan=result.plan;if(plan.goal)draft.goal=plan.goal;activeId=null;busy=false;navigate('plan');toast(t('已完成聯網 AI 草稿，請核對後使用。','Live AI draft ready. Please review before use.'));}catch(e){busy=false;const node=$('#ai-error');if(node)node.innerHTML=`<div class="notice warm">${esc(errorText(e.message))} <button class="inline-link" data-nav="about">${t('連線狀態 ↗','Connection settings ↗')}</button></div>`;toast(errorText(e.message));document.querySelectorAll('[data-ai],[data-sample]').forEach(x=>x.disabled=false);updateStatus();}}
function getPlanSources(){return Array.isArray(plan?.sources)&&plan.sources.length?plan.sources:sources;}
function sourceMeta(s){const local=s[lang];return{title:local?.title||s.title||s.id,finding:local?.finding||'',scope:local?.scope||'',limit:local?.limit||'',url:s.url,updated:s.updated,kind:s.contentKind||'reviewed-summary'};}
const evaluationLabels=()=>[['lookFor',t('看甚麼學習表現？','What learning should be visible?')],['recordHow',t('怎樣簡單記錄？','How can I record it quickly?')],['continueWhen',t('何時值得繼續？','When should I keep using it?')],['adjustWhen',t('何時先調整？','When should I adapt it?')],['tryDifferentWhen',t('何時考慮換方法？','When should I try another approach?')]];
function editablePlanField(key,label){if(key==='knowledgePathText')plan.knowledgePathText=(plan.knowledgePath||[]).join('\n');return `<div class="plan-section"><label class="field-label" for="${key}">${label}</label><textarea class="plan-edit" id="${key}" data-extra="${key}" maxlength="2500">${esc(plan[key])}</textarea><div class="print-value" hidden>${esc(plan[key])}</div></div>`;}
function evaluationView(){if(!plan.evaluation)return `<div class="notice">${t('這是較早儲存的活動，未附判斷準則。可在備註補充要觀察的表現及下一步。','This older activity has no decision guide. Add observable outcomes and next steps in your notes.')}</div>`;return `<section class="plan-section evaluation-section"><h2>${t('試過之後，怎樣決定下一步？','After the trial, how will I decide?')}</h2><p class="subtext">${t('以下是可修改的參考準則。學生是否學會，比活動是否熱鬧更重要；一次觀察不足以證明成效。','Adjust these suggested criteria. Check learning as well as participation. One observation cannot establish impact.')}</p>${evaluationLabels().map(([key,label])=>`<div class="field"><label for="eval-${key}">${label}</label><textarea id="eval-${key}" class="plan-edit" data-evaluation="${key}" maxlength="2000">${esc(plan.evaluation[key])}</textarea><div class="print-value" hidden>${esc(plan.evaluation[key])}</div></div>`).join('')}</section>`;}
function planView(){
 if(!plan)plan=samplePlan(draft,lang);
 const rich=detailedPlanView(),start=rich.indexOf('<article class="form-panel">')+'<article class="form-panel">'.length,end=rich.indexOf('</article>',start);
 const detail=rich.slice(start,end).replace(/<div class="form-actions">[\s\S]*$/,'');
 const chain=Array.isArray(plan.knowledgePath)?plan.knowledgePath:[];
 return `${heading('CLASSROOM FLOW',esc(plan.title),t('先看知識點怎樣串連，再按流程帶活動。','See how the ideas connect, then use the classroom flow.'),`<div class="output-actions">${b(t('複製流程','Copy flow'),'data-action="copy"','secondary')}${b(t('列印流程／PDF','Print flow / PDF'),'data-action="print"','secondary')}</div>`)}${summary()}<article class="form-panel compact-plan"><span class="tag ${plan.origin==='ai'?'green':'orange'}">${plan.origin==='ai'?`AI · ${esc(plan.model)}`:t('示範活動 · 不是 AI 結果','Fixed sample · not an AI result')}</span>${plan.origin==='ai'?`<p class="source-citation">${t('生成時間','Generated')}: ${esc(new Date(plan.generatedAt).toLocaleString(en?'en-HK':'zh-HK'))} · ${plan.search?.completed?t('已檢索研究來源；詳情內可核對','Research retrieved; check sources in details'):t('使用已核對摘要；詳情內可核對','Reviewed summaries; check sources in details')}</p>`:''}<h2>${t('學習目標','Learning goal')}</h2><p>${esc(plan.goal||draft.goal)}</p>${draft.reuseContext?`<p class="source-citation">${t('沿用自','Based on')}: ${esc(draft.reuseContext.title)}</p>`:''}${plan.revisionNotes?.length?`<div class="notice"><strong>${t('這次改了甚麼','What changed')}</strong><ul>${plan.revisionNotes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${plan.feedbackFollowUp?`<details class="context-settings"><summary>${t('AI 怎樣回應所選回顧','How selected feedback was used')}</summary><p>${esc(plan.feedbackFollowUp)}</p></details>`:''}${chain.length?`<section class="knowledge-path"><h3>${t('知識點怎樣串連','How the knowledge connects')}</h3><ol>${chain.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>`:''}<section class="flow-stages">${plan.steps.map((s,i)=>`<div class="flow-stage"><div class="flow-stage-heading"><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(s.title)}</h3><small>${s.minutes} ${t('分鐘','min')}</small></div>${s.concept?`<p class="concept-focus">${esc(s.concept)}</p>`:''}<p>${esc(s.text)}</p>${s.check?`<p class="flow-check"><strong>${t('看甚麼','Check')}: </strong>${esc(s.check)}</p>`:''}${s.bridge?`<p class="flow-bridge">↳ ${esc(s.bridge)}</p>`:''}</div>`).join('')}</section><div class="flow-bottom"><section><h3>${t('準備','Prepare')}</h3><p>${esc(plan.materials||'')}</p><h3>${t('離堂前檢查','Exit check')}</h3><p>${esc(plan.exitCheck||'')}</p></section><section><h3>${t('下次是否繼續？','Use it again?')}</h3>${['continueWhen','adjustWhen','tryDifferentWhen'].filter(k=>plan.evaluation?.[k]).map(k=>`<p><strong>${({continueWhen:t('繼續','Keep'),adjustWhen:t('調整','Adapt'),tryDifferentWhen:t('考慮轉換','Reconsider')})[k]}: </strong>${esc(plan.evaluation[k])}</p>`).join('')}</section></div>${plan.cautions?.length?`<details class="context-settings"><summary>${t('實施前留意','Before trying this')} · ${plan.cautions.length}</summary>${plan.cautions.map(x=>`<p>${esc(x)}</p>`).join('')}</details>`:''}<details class="plan-details" ${planEditing?'open':''}><summary>${t('修改活動、查看提問示例與設計依據','Edit the activity, optional prompts & design notes')}</summary><p class="subtext">${t('修改後按「套用修改」更新上方流程。提問只作參考，可按教學需要選用。','Apply edits to update the flow above. Teacher questions are optional examples.')}</p>${chain.length?editablePlanField('knowledgePathText',t('知識點銜接（每行一項）','Knowledge connections (one per line)')):''}${plan.steps.map((s,i)=>`<div class="field"><label>${t('環節','Stage')} ${i+1} · ${t('知識重點／銜接／檢查','Concept / bridge / check')}</label>${['concept','bridge','check'].map(k=>`<label class="subtext" for="stage-${i}-${k}">${({concept:t('知識重點','Concept'),bridge:t('銜接下一步','Bridge'),check:t('學習檢查','Check')})[k]}</label><textarea class="plan-edit" id="stage-${i}-${k}" data-stage-index="${i}" data-stage-key="${k}" maxlength="1000">${esc(s[k]||'')}</textarea><div class="print-value" hidden>${esc(s[k]||'')}</div>`).join('')}</div>`).join('')}${detail}<div class="output-actions">${b(t('套用修改','Apply edits'),'data-action="apply-plan"')}${b(t('複製完整版本','Copy full version'),'data-action="copy-full"','secondary')}${b(t('列印完整版本','Print full version'),'data-action="print-full"','secondary')}</div></details><div class="form-actions">${b(t('儲存活動','Save activity'),'data-action="save"')}${b(t('課後回顧 →','Classroom reflection →'),'data-action="reflect"','secondary')}</div></article>`;
}
function detailedPlanView(){if(!plan)plan=samplePlan(draft,lang);const ai=plan.origin==='ai';return `${heading('02 / EDIT & USE',esc(plan.title),t('編輯草稿、核對來源，再安排一次課堂嘗試。','Edit the draft, check its sources and plan a classroom trial.'),`<div class="output-actions">${b(t('複製活動','Copy activity'),'data-action="copy"','secondary')}${b(t('列印／另存 PDF ↗','Print / save as PDF ↗'),'data-action="print"','secondary')}</div>`)}${steps(2)}${summary()}<div class="layout-two"><article class="form-panel"><span class="tag ${ai?'green':'orange'}">${ai?`AI · ${esc(plan.model)}`:t('示範活動 · 不是 AI 結果','Rule-based sample · not an AI result')}</span>${ai?`<p class="source-citation">${t('生成時間','Generated')}: ${esc(new Date(plan.generatedAt).toLocaleString(en?'en-HK':'zh-HK'))} · ${plan.search?.completed?plan.search.mode==='reviewed-pages'?t(`已即時讀取 ${plan.search.count} 份研究來源`,`Live retrieval: ${plan.search.count} reviewed research pages`):t(`聯網搜尋：${plan.search.count} 個來源`,`Live search: ${plan.search.count} sources`):plan.search?.warning?t('研究頁面暫未能讀取，使用已核對摘要','Live pages unavailable; using reviewed summaries'):t('未啟用即時檢索','Live retrieval disabled')}</p>`:''}<h2 style="margin-top:18px">${esc(plan.goal||draft.goal)}</h2>${plan.feedbackFollowUp?`<div class="notice"><strong>${t('已參考你勾選的回顧','Your selected feedback was used')}</strong><p>${esc(plan.feedbackFollowUp)}</p></div>`:''}${[['learningRationale',t('活動怎樣對應目標','How the activity addresses the goal')],['prerequisiteCheck',t('開始前，先了解學生','Check readiness first')]].filter(([key])=>plan[key]).map(([key,label])=>editablePlanField(key,label)).join('')}${editablePlanField('support',t('支援安排','Support'))}<div class="timeline">${plan.steps.map((s,i)=>`<div class="timeline-item"><div class="timeline-time">${s.minutes} ${t('分鐘','min')}<br>0${i+1}</div><div><h4>${esc(s.title)}</h4><textarea class="plan-edit" data-step="${i}" aria-label="${t('步驟','Step')} ${i+1}" maxlength="3500">${esc(s.text)}</textarea><div class="print-value" hidden>${esc(s.text)}</div></div></div>`).join('')}</div>${[['teacherPrompts',t('可直接使用的提問與句式','Teacher prompts')],['studentTask',t('學生任務','Pupil task')],['exitCheck',t('快速學習檢查','Quick learning check')]].filter(([key])=>plan[key]).map(([key,label])=>`<div class="plan-section"><label class="field-label" for="${key}">${label}</label><textarea class="plan-edit" id="${key}" data-extra="${key}" maxlength="2000">${esc(plan[key])}</textarea><div class="print-value" hidden>${esc(plan[key])}</div></div>`).join('')}${editablePlanField('materials',t('材料與準備','Materials & preparation'))}<div class="plan-section"><h3>${t('先觀察甚麼？','What to observe')}</h3><ul class="observation-list">${(plan.observations||samplePlan(draft,lang).observations).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${evaluationView()}<div class="plan-section"><label for="teacher-note" class="field-label">${t('我的調整與備註','My changes & notes')}</label><textarea id="teacher-note" class="plan-edit" maxlength="2500">${esc(plan.teacherNote)}</textarea><div class="print-value" hidden>${esc(plan.teacherNote)}</div></div><details class="plan-section evidence-details"><summary>${t('為甚麼建議這個安排？（研究依據與局限）','Why this approach? (evidence & limits)')}</summary>${(plan.evidence||[]).map(e=>{const s=getPlanSources().find(a=>a.id===e.sourceId);return `<div class="evidence-note"><strong>${esc(sourceMeta(s||{}).title)}</strong><p><strong>${t('研究提到甚麼','Research finding')}</strong><br>${esc(e.finding)}</p>${e.application?`<p><strong>${t('這次怎樣用（活動改編）','How it is adapted for this class')}</strong><br>${esc(e.application)}</p>`:''}<p><strong>${t('有甚麼局限','Limits')}</strong><br>${esc(e.limitation)}</p>${s?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${t('核對原始來源 ↗','Check the original source ↗')}</a><div class="source-citation">${esc(s.url)}</div>`:''}</div>`;}).join('')}<p class="subtext">${t('活動步驟屬於產品／AI 改編，未經這些研究直接驗證。','The activity is a product / AI adaptation, not a directly validated intervention from these sources.')}</p>${(plan.cautions||[]).map(x=>`<div class="notice warm">${esc(x)}</div>`).join('')}${plan.timingAdjusted?`<div class="notice">${t('AI 時間分配已由系統調整至所選總時長，請核對可行性。','AI stage durations were adjusted to your selected total. Please check feasibility.')}</div>`:''}</details><div class="form-actions"><button class="text-button" data-nav="home">← ${t('修改課題及安排','Edit topic & settings')}</button><div style="display:flex;gap:9px;flex-wrap:wrap">${b(t('儲存活動','Save activity'),'data-action="save"')}${b(t('課後回顧 →','Classroom reflection →'),'data-action="reflect"','secondary')}</div></div></article><aside><div class="side-card"><span class="mini-label">TEACHERS DECIDE</span><h3>${t('把它變成你的活動','Make it your own')}</h3><p>${t('核對內容與依據；按照學生已有知識及表達需要調整。草稿與研究結論需要分開看。','Check the content and evidence, then adapt to prior knowledge and language needs. A generated draft is separate from a research finding.')}</p><button class="inline-link" data-nav="guide">${names.guide} ↗</button></div><div class="notice">${t('紀錄只存於此瀏覽器。請定期下載備份。','Records stay in this browser. Download backups regularly.')}</div></aside></div>`;}
function syncPlan(){if(!plan)return;document.querySelectorAll('[data-stage-key]').forEach(x=>plan.steps[+x.dataset.stageIndex][x.dataset.stageKey]=x.value);if($('[data-extra=knowledgePathText]'))plan.knowledgePath=$('[data-extra=knowledgePathText]').value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,8);document.querySelectorAll('[data-step]').forEach(x=>plan.steps[+x.dataset.step].text=x.value);document.querySelectorAll('[data-extra]').forEach(input=>plan[input.dataset.extra]=input.value);document.querySelectorAll('[data-evaluation]').forEach(input=>{plan.evaluation??={};plan.evaluation[input.dataset.evaluation]=input.value;});if($('#teacher-note'))plan.teacherNote=$('#teacher-note').value;}
function save(quiet=false){syncPlan();const id=activeId||crypto.randomUUID(),old=records.find(r=>r.id===id),r={id,title:plan.title,draft:structuredClone(draft),plan:structuredClone(plan),reflection:old?.reflection||null,reflectionAI:old?.reflectionAI||null,feedbackHistory:old?.feedbackHistory||[],favorite:old?.favorite===true,notes:old?.notes||[],created:old?.created||new Date().toISOString(),updated:new Date().toISOString()};const prev=records;records=[r,...records.filter(x=>x.id!==id)];if(!persist()){records=prev;return false;}activeId=id;$('#saved-count').textContent=records.length;if(!quiet)toast(t('活動已儲存。','Activity saved.'));return true;}
function open(id,next='plan'){const r=records.find(x=>x.id===id);if(!r)return;draft=structuredClone(r.draft);documentImport={text:draft.documentContext||'',name:draft.documentName||'',suggestion:null,notes:'',consent:false,error:'',attached:Boolean(draft.documentContext)};plan=structuredClone(r.plan);activeId=id;navigate(next);}
function reflectView(){const r=records.find(x=>x.id===activeId),f=r?.reflection||{},ai=r?.reflectionAI;return `${heading('03 / REFLECT & REFINE',t('帶着觀察，回到這裏。','Return with your observations.'),t('具體記錄發生了甚麼，再決定下一次怎樣調整。','Record what happened, then decide what to refine.'))}${steps(3)}<div class="layout-two"><form id="reflection-form" class="form-panel"><span class="tag green">${esc(plan?.title)}</span>${plan?.evaluation?`<details class="plan-section" open><summary>${t('原先訂下的觀察與判斷準則','Your planned checks and decision criteria')}</summary>${evaluationLabels().map(([key,label])=>`<p><strong>${label}</strong><br>${esc(plan.evaluation[key])}</p>`).join('')}</details>`:''}<div class="field" style="margin-top:24px"><label for="lesson-date">${t('課堂日期','Lesson date')}</label><input id="lesson-date" name="date" type="date" required value="${esc(f.date||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Hong_Kong',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()))}"></div><div class="field-grid"><div class="field"><label for="actual">${t('實際時間（分鐘）','Actual duration (minutes)')}</label><input type="number" id="actual" name="actual" min="1" max="180" required value="${esc(f.actual||draft.minutes)}"></div><div class="field"><label for="participation">${t('教師觀察的參與情況','Observed participation')}</label><select id="participation" name="participation">${[t('尚未能判斷','Not yet clear'),t('少數學生參與','A few pupils'),t('約一半學生參與','About half the class'),t('大部分學生參與','Most of the class')].map(v=>`<option ${v===f.participation?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="field"><label for="decision">${t('這次的教學判斷','My decision after this trial')}</label><select id="decision" name="decision">${[['uncertain',t('仍需更多觀察','Need more observations')],['keep',t('值得繼續','Keep using it')],['adapt',t('調整後再試','Adapt and try again')],['change',t('考慮換方法','Consider another approach')]].map(([id,label])=>`<option value="${id}" ${f.decision===id?'selected':''}>${label}</option>`).join('')}</select></div>${[['observation',t('對照學習目標，你看見或聽見甚麼？','What did you see or hear in relation to the learning goal?')],['difficulty',t('哪裏遇到困難？','What was difficult?')],['next',t('下一次想怎樣調整？','What would you change next time?')]].map(([k,title])=>`<div class="field"><label for="${k}">${title}${k==='observation'?' *':''}</label><textarea id="${k}" name="${k}" maxlength="2000" ${k==='observation'?'required':''}>${esc(f[k]||'')}</textarea></div>`).join('')}<div class="notice">${t('一次觀察不能證明活動造成了某種改變。AI 只能提出待教師判斷的建議。','One observation does not show that an activity caused a change. AI suggestions require teacher judgement.')}</div><div class="form-actions"><button type="button" class="text-button" data-nav="plan">← ${names.plan}</button><button type="submit" class="button">${t('儲存回顧 ✓','Save reflection ✓')}</button></div><div style="margin-top:18px">${b(t('儲存並請 AI 建議下一步 ↗','Save & ask AI for next steps ↗'),'type="button" data-action="reflect-ai"','secondary')}</div>${feedbackHistoryView(r)}${ai?`<div class="plan-section"><h3>${t('AI 建議 · 非成效結論','AI suggestions · not an impact conclusion')}</h3>${['keep','adjust','uncertainty'].map((k,i)=>`<div class="evidence-note"><strong>${t(['值得保留','可作調整','仍不確定'][i],['Worth keeping','Possible adjustments','Still uncertain'][i])}</strong><ul>${ai.result[k].map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`).join('')}<p class="source-citation">${esc(ai.meta.model)} · ${esc(new Date(ai.meta.generatedAt).toLocaleString())}</p></div>`:''}</form><aside><div class="side-card"><h3>${t('具體，比好壞更有用','Specific beats good or bad')}</h3><p>${t('記下你看見、聽見的事，保留不同解釋。請勿加入學生身分資料。','Record what you saw or heard, and keep alternative explanations open. Do not include pupil-identifying information.')}</p></div></aside></div>`;}
function feedbackHistoryView(r){if(!r?.feedbackHistory?.length)return '';return `<details class="plan-section feedback-log"><summary>${t('已保存的回顧紀錄','Saved reflection log')} (${r.feedbackHistory.length})</summary>${[...r.feedbackHistory].reverse().map(entry=>`<article><h4>${esc(entry.snapshot.date||'')} · ${esc(new Date(entry.created).toLocaleString())}</h4><p>${esc(entry.snapshot.observation)}</p>${entry.snapshot.difficulty?`<p>${t('困難','Difficulty')}: ${esc(entry.snapshot.difficulty)}</p>`:''}${entry.snapshot.next?`<p>${t('下一步','Next step')}: ${esc(entry.snapshot.next)}</p>`:''}${entry.ai?`<details><summary>${t('當時的 AI 建議','AI suggestions at the time')}</summary>${['keep','adjust','uncertainty'].map(key=>`<ul>${entry.ai.result[key].map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`).join('')}</details>`:''}</article>`).join('')}</details>`;}
function saveReflection(){const f=$('#reflection-form');if(!f.reportValidity())return false;const data=Object.fromEntries(new FormData(f));if(!data.observation.trim())return false;const current=records.find(x=>x.id===activeId);if(!current)return false;let next;try{next=appendFeedback(current,data);}catch{toast(t('此活動回顧已達上限，請先下載備份。','This activity’s reflection log is full. Download a backup first.'));return false;}const previous=records;records=records.map(x=>x.id===activeId?next:x);if(!persist()){records=previous;return false;}return true;}
async function reflectAI(){if(!saveReflection())return;const r=records.find(x=>x.id===activeId);if(!api.configured){toast(errorText('AI_NOT_CONFIGURED'));return;}if(!confirm(t('把本次回顧、同活動最近三次過往回顧及目標／判斷準則交給 AI，以取得調整建議？請先確認沒有學生身分資料。','Send this reflection, up to three previous reflections for this activity, and the goal/decision criteria to the configured AI service? Confirm there are no pupil-identifying details.')))return;draft.consent=true;busy=true;updateStatus();try{const result=await aiRequest('reflect',{reflection:r.reflection,previousReflections:(r.feedbackHistory||[]).slice(0,-1).slice(-3).map(x=>x.snapshot),planContext:{goal:r.plan.goal||r.draft.goal,evaluation:r.plan.evaluation||{},exitCheck:r.plan.exitCheck||''}});r.reflectionAI={result:result.reflection,meta:result.meta};if(r.feedbackHistory?.length)r.feedbackHistory.at(-1).ai=structuredClone(r.reflectionAI);persist();busy=false;navigate('reflect');}catch(e){busy=false;toast(errorText(e.message));updateStatus();}}
function historyView(){const items=records.filter(r=>!onlyFavorites||r.favorite).sort((a,b)=>Number(b.favorite)-Number(a.favorite)||String(b.updated).localeCompare(String(a.updated)));return `${heading('MY TEACHING TRIALS',t('每一次嘗試，都留下線索。','Keep a record of each teaching trial.'),t('收藏值得再用的活動，保留回顧及每次調整。','Favorite useful activities and keep reflections and adjustments.'),b(t('新活動 ＋','New activity ＋'),'data-action="new"'))}<div class="notice">${t('活動、收藏、自訂提示及回顧只保存在目前瀏覽器。下載備份可保留並轉移到其他裝置。','Activities, favorites, prompts and reflections stay in this browser. Download a backup to keep them or move devices.')}</div><div class="history-toolbar">${b(t('全部活動','All activities'),`data-action="show-all" aria-pressed="${!onlyFavorites}"`,'secondary')}${b(t('只看收藏 ♥','Favorites ♥'),`data-action="show-favorites" aria-pressed="${onlyFavorites}"`,'secondary')}${b(t('下載全部備份 ↓','Download all records ↓'),'data-action="export"','secondary')}<label class="button secondary" for="import-file">${t('匯入備份 ↑','Import backup ↑')}</label><input id="import-file" type="file" accept="application/json,.json" hidden></div>${items.length?`<div class="history-grid">${items.map(r=>`<article class="history-card"><div class="history-card-top"><span class="tag ${r.reflection?'green':'orange'}">${r.reflection?t('已完成回顧','Reviewed'):t('待課堂嘗試','Ready to try')}</span><button class="favorite-button ${r.favorite?'is-favorite':''}" data-favorite="${esc(r.id)}" aria-pressed="${r.favorite===true}" aria-label="${r.favorite?t('取消收藏','Remove favorite'):t('收藏活動','Favorite activity')}: ${esc(r.title)}">${r.favorite?'♥':'♡'} ${t('收藏','Favorite')}</button></div><h2>${esc(r.title)}</h2><p>${esc(curricula[r.draft.curriculum||'hk'][lang])} · ${esc(stageLabel(r.draft,lang))} · ${r.draft.minutes} ${t('分鐘','minutes')} · ${r.plan.origin==='ai'?'AI':t('示例','Sample')}</p><p>${esc(r.draft.goal)}</p>${r.reflection?`<div class="reflection-summary">${esc(r.reflection.next||r.reflection.observation)}<small>${t('已保留回顧','Reflections retained')}: ${r.feedbackHistory?.length||1}</small></div>`:''}<div class="history-actions">${b(t('沿用並改進','Reuse & improve'),`data-reuse="${esc(r.id)}"`,'secondary')}${b(t('開啟活動 →','Open activity →'),`data-open="${esc(r.id)}"`,'secondary')}<button class="text-button" data-review="${esc(r.id)}">${names.reflect}</button><button class="danger-button" data-delete="${esc(r.id)}">${t('刪除','Delete')}</button></div></article>`).join('')}</div>`:`<div class="empty-state"><h2>${onlyFavorites?t('還未有收藏的活動。','No favorites yet.'):t('從第一次小嘗試開始。','Start with your first small trial.')}</h2><p>${onlyFavorites?t('在活動卡按愛心，就能在這裏快速找到。','Click a heart on an activity to find it here.'):t('儲存活動後，它會顯示在這裏。','Saved activities will appear here.')}</p></div>`}`;}
function libraryView(){return homeView();}
function mobileInstallGuide(){return `<section id="install-guide" class="install-guide" aria-labelledby="install-title"><p class="eyebrow">PHONE · HOME SCREEN</p><h2 id="install-title">${t('手機使用：加至主畫面','Use it from your phone’s Home Screen','手机使用：添加到主屏幕')}</h2><p class="subtext">${t('加入後會有桌面圖示，可像 App 一樣開啟；不用下載安裝包。AI 生成仍需連網。','Add an icon to open the site like an app, without downloading an installation package. AI generation still needs the internet.','添加后会有桌面图标，可像 App 一样打开，无需下载安装包。AI 生成仍需联网。')}</p><div class="install-cards"><div class="install-card"><h3>iPhone · Safari</h3><ol><li>${t('用 Safari 開啟本網站；如在微信內，先複製網址，再到 Safari 貼上開啟。','Open this website in Safari. From WeChat or another in-app browser, copy the URL and open it in Safari.','用 Safari 打开本网站；如果在微信内，先复制网址，再到 Safari 粘贴打开。')}</li><li>${t('點「分享」（向上箭頭）；部分版本要先點頁面選單或「⋯」，再選「分享」。','Tap Share (the upward arrow). Some layouts place Share inside the page menu or More.','点“共享／分享”（向上箭头）；部分版本需先点页面菜单或“⋯”，再选共享。')}</li><li>${t('選「加至主畫面」。如看到「開啟為網頁 App」，請開啟。','Choose Add to Home Screen. Turn on Open as Web App if that option appears.','选“添加到主屏幕”。如出现“作为网页 App 打开”，请开启。')}</li><li>${t('確認名稱，再點「加入」；日後從主畫面的圖示開啟。','Confirm the name and tap Add. Use the new Home Screen icon next time.','确认名称，再点“添加”；以后从主屏幕图标打开。')}</li></ol><a href="${t('https://support.apple.com/zh-hk/guide/iphone/iphea86e5236/ios','https://support.apple.com/guide/iphone/iphea86e5236/ios','https://support.apple.com/zh-cn/guide/iphone/iphea86e5236/ios')}" target="_blank" rel="noopener noreferrer">${t('Apple 官方步驟 ↗','Apple’s instructions ↗','Apple 官方步骤 ↗')}</a></div><div class="install-card"><h3>Android · Chrome</h3><ol><li>${t('用 Chrome 開啟本網站；如在其他 App 內，先複製網址到瀏覽器。','Open this website in Chrome. Copy the URL into your browser if you are inside another app.','用 Chrome 打开本网站；如果在其他 App 内，先复制网址到浏览器。')}</li><li>${t('點右上角「⋮」選單，尋找「加至主畫面」或「安裝應用程式」。','Open the ⋮ menu and look for Add to Home screen or Install app.','点右上角“⋮”菜单，找“添加到主屏幕”或“安装应用”。')}</li><li>${t('按畫面提示選「安裝」或「建立捷徑／加入」，再從桌面圖示開啟。','Follow the prompt to install or create/add a shortcut, then open the Home Screen icon.','按提示选“安装”或“创建快捷方式／添加”，再从桌面图标打开。')}</li></ol><p>${t('其他 Android 瀏覽器可在選單尋找「加入桌面」等選項；名稱及支援情況視版本而定。若沒有該選項，仍可直接用網址。','Other Android browsers may offer Add to desktop or a similar option. Names and support vary; the normal website still works without it.','其他 Android 浏览器可在菜单找“添加到桌面”等选项，名称及支持情况依版本而异；没有该选项也可直接用网址。')}</p><a href="https://support.google.com/chrome/answer/9658361?co=GENIE.Platform%3DAndroid" target="_blank" rel="noopener noreferrer">${t('Chrome 官方步驟 ↗','Chrome’s instructions ↗','Chrome 官方步骤 ↗')}</a></div></div><div class="install-footnote"><strong>${t('找不到選項？','Can’t find the option?','找不到选项？')}</strong> ${t('iPhone 可在分享清單底部選「編輯動作」，加入「加至主畫面」。先用 Safari 或 Chrome 開啟，不要停留在 App 內置瀏覽器。','On iPhone, use Edit Actions at the bottom of the sharing sheet to add Add to Home Screen. Open the site in Safari or Chrome rather than an in-app browser.','iPhone 可到共享列表底部的“编辑操作”加入“添加到主屏幕”。先用 Safari 或 Chrome 打开，不要停留在 App 内置浏览器。')}<p>${t('記錄仍保存在目前瀏覽器／網頁 App。不同瀏覽器、桌面圖示或網址未必共用記錄，轉換前請先下載備份，需要時再匯入。加至主畫面不會改善原有網址的網絡連線。','Records remain in the current browser or web app. Browsers, Home Screen apps and domains may not share storage. Download a backup before switching and import it if needed. Adding an icon does not fix connectivity to the original URL.','记录仍保存在当前浏览器／网页 App。不同浏览器、桌面图标或网址可能不共享记录，切换前请先下载备份，需要时再导入。添加到主屏幕不会改善原网址的网络连接。')}</p></div></section>`;}

function guideView(){return `${heading('USER GUIDE · v0.6',t('從備課到回顧，一步步完成。','From planning to reflection, step by step.'),t('可自行填寫，也可匯入 Word；生成後仍由教師核對。','Enter context yourself or import Word. Review every generated draft.'),`<a class="button secondary" href="/docs/user-guide-${lang}.md" download>${t('下載完整說明','Download full guide')} ↓</a>`)}${mobileInstallGuide()}${workflowGuide()}<article class="about-prose"><h2>${t('1. 課程、科目及目標','1. Curriculum, subject and goal')}</h2><p>${t('選香港、內地或國際課程，再選階段及科目。科目清單只作常見起點，可填校本科目；國際課程請補充 IB、Cambridge、AP 等實際課綱及年級。填寫人數、時間、課題、學生基礎／困難及可觀察的目標。','Choose Hong Kong, mainland or international context, stage and subject. Lists are common starting points; custom subjects are supported. Specify the actual programme and year. Complete class size, time, topic, prior learning/needs and an observable goal.')}</p><h2>${t('2. Word 匯入（選用）','2. Word import (optional)')}</h2><p>${t('選 .docx（最多 5 MB）。瀏覽器只讀取正文及表格文字（最多 20,000 字），不讀圖片、批注及頁首頁尾；不支援加密或舊 .doc。原檔不會上傳。先核對及刪去個人資料，勾選同意，再按「AI 解析教案」。確認結果後才套用到表格，未提及的資料由老師補充。修改文字後須重新解析。套用後的文字會供生成參考，並隨活動保存在此瀏覽器。','Choose .docx (up to 5 MB). The browser reads body/table text (up to 20,000 characters), excluding images, comments and headers/footers. Encrypted and legacy .doc are unsupported. The original file is not uploaded. Remove identifying data, review and consent, then analyse with AI. Review the results before applying. Fill missing context yourself and reanalyse edited text. Applied text is used in generation and saved with that browser-local activity.')}</p><h2>${t('3. 自訂快捷提示','3. Prompt shortcuts')}</h2><p>${t('在「自訂教學提示」輸入偏好，按「把這段提示儲存為快捷按鈕」，填名稱儲存。下次點名稱即可套用到提示框，可修改後生成，不覆蓋學習目標。最多儲存 30 個，備份會一併保留。','Write a preference, save it as a named shortcut, then click the name next time. Edit before generating; this does not replace the learning goal. Save up to 30 shortcuts; backups include them.')}</p><h2>${t('4. 生成、修改及收藏','4. Generate, edit and favorite')}</h2><p>${t('同意 AI 處理後生成，核對目標、活動、支援、材料、學習檢查及下一步準則，再修改、儲存、複製或列印。研究依據及局限在活動內展開。歷史頁按愛心收藏，再用「只看收藏」找回；收藏不消耗 AI 額度。','Consent and generate. Review goal alignment, tasks, support, materials, learning checks and decision criteria. Edit, save, copy or print. Expand the research notes inside the activity. Favorite activities with the heart and filter Favorites later; favoriting uses no AI credit.')}</p><h2>${t('5. 回顧留底與 AI 跟進','5. Reflection records and AI follow-up')}</h2><p>${t('課後寫觀察、困難、下一步及教師判斷。儲存改動會新增回顧快照，舊內容保留，相同內容不重複新增。AI 建議須另行確認，會參考本次及同活動最近三次過往回顧。新活動可勾選最多三個活動的最新回顧摘要，AI 會說明怎樣回應。這是使用上下文改善建議，不是自動訓練或微調模型。參與不等於理解，一次觀察不代表因果。','Record observations, difficulties, next steps and your decision. Changed saves add snapshots without overwriting old reflections; identical content is not duplicated. AI suggestions need separate confirmation and use the current reflection plus up to three earlier ones for that activity. New activities can use latest excerpts from up to three selected activities, with an explanation of the adaptation. This is contextual follow-up, not automatic training or fine-tuning. Participation is not proof of understanding and one observation cannot establish impact.')}</p><h2>${t('6. 三種語言、備份及私隱','6. Three languages, backups and privacy')}</h2><p>${t('同一網址右上角切換香港繁體、簡體中文及英文，不會翻譯已儲存的原始內容。活動、收藏、提示、匯入文字及回顧只存於目前瀏覽器，不自動跨裝置同步。請在歷史頁下載備份；新版接受舊備份，相同編號保留現有版本。清除瀏覽器資料可能失去紀錄。請勿加入學生姓名、聯絡資料或診斷報告。教師現時免費使用，AI 受帳戶額度及暫時頻率限制；固定示範會標示不是 AI 結果。','Switch between Hong Kong Traditional Chinese, Simplified Chinese and English at the same URL. Saved original content is not translated. Activities, favorites, prompts, imported text and reflections stay in this browser without automatic device sync. Download a backup; older backups are accepted and existing IDs are kept. Clearing browser data may remove records. Exclude names, contact details and diagnostic reports. Teachers currently use the tool free; AI has service-credit and temporary limits. Fixed samples are labelled as not AI results.')}</p>${b(t('開始設計活動 →','Design an activity →'),'data-nav="home"')}</article>`;}

function aboutView(){return `${heading('FREE TEACHER WORKSPACE',t('免費使用，專注教學。','Free to use. Focused on teaching.'),t('毋須學生帳號、教師訂閱或試用碼。','No pupil accounts, teacher subscriptions or access codes.'))}<article class="about-prose"><h2>${t('目前 AI 狀態','AI availability')}</h2><p><span class="tag ${api.configured?'green':'orange'}">${api.configured?t('已設定 AI，可嘗試生成','AI configured; ready to try'):t('AI 暫未啟用，示範活動可照常使用','AI not enabled; samples remain available')}</span></p><p>${t('模型','Model')}: <strong>${esc(api.model)}</strong><br>${t('研究來源','Research sources')}: ${api.liveSearch?(api.retrievalMode==='reviewed-pages'?t('生成前即時讀取已收錄的研究頁面','Reviewed research pages retrieved before generation'):t('生成前聯網搜尋','Live search before generation')):t('目前使用已收錄的研究摘要','Curated research summaries')}</p><p>${t('設定狀態不代表已成功生成。成功的 AI 活動會列出模型、生成時間及來源；示範活動會另外標示。','Configuration is not proof of a successful generation. AI activities show the model, generation time and sources; samples are labelled separately.')}</p><button class="button secondary" data-action="refresh-status">${t('重新檢查狀態','Refresh status')}</button><h2>${t('免費使用安排','Free access')}</h2><p>${t('目前所有功能均不向教師收費，也毋須輸入密鑰或試用碼。AI 受服務額度及使用頻率限制；暫時未能生成時，仍可使用示範活動、修改、儲存、列印及課後回顧。','Teachers are not charged for any current feature and do not enter keys or codes. AI is subject to service credit and usage limits. Samples, editing, saving, printing and reflection remain available when AI is unavailable.')}</p><h2>${t('紀錄與私隱','Records & privacy')}</h2><p>${t('活動及回顧保存在此瀏覽器。使用 AI 前須確認資料傳送：你提交的內容會交由網站設定的模型服務處理。請勿加入學生姓名、聯絡資料或診斷報告，並遵守學校的資料處理安排。','Activities and reflections stay in this browser. AI requires consent to send the submitted content to the configured service. Exclude pupil names, contact details and diagnostic reports, and follow your school’s data-handling rules.')}</p><details><summary>${t('網站管理員：AI 接入及額度','Site owner: AI connection and credit')}</summary><p>${t('Vercel 部署可使用 AI Gateway 的項目身分認證，或由管理員在伺服器端設定密鑰。亦可設定 DEEPSEEK_API_KEY 或 OPENAI_API_KEY 直接接入；密鑰不會交給教師或瀏覽器。預設 Gateway 模型為 DeepSeek V4.1 Flash。教師毋須自行設定。實際可用性取決於 Vercel 身分認證、模型權限及帳戶額度。','Vercel deployments can authenticate to AI Gateway using the project identity, or the owner can configure a server-side key. DEEPSEEK_API_KEY and OPENAI_API_KEY also support direct connections; teachers and browser code never receive them. The prepared Gateway default is DeepSeek V4.1 Flash. Teachers do not configure it. Availability depends on Vercel authentication, model access and account credit.')}</p><p>${t('AI Gateway 模式會即時讀取研究庫中的 EEF 原始頁面，並非全網搜尋。直接連接 DeepSeek 或 OpenAI 時則保留搜尋模式。所有來源仍需教師核對。','Gateway mode retrieves the curated EEF source pages live; it does not search the whole web. Direct DeepSeek and OpenAI connections retain web search. Teachers should check all sources.')}</p><p>${t('額度及收費由供應商管理；網站不會自動購買額度。公開使用前，管理員應在供應商帳戶設定預算或停用自動增值。網站內的記憶體限流只按運行實例計算，並非全站硬性支出上限。','Credit and billing are managed by the provider; this site does not purchase credits. Set provider budgets or disable automatic top-ups before public use. In-memory request limits apply per running instance and are not a site-wide hard spending cap.')}</p><a href="https://vercel.com/docs/ai-gateway/authentication-and-byok" target="_blank" rel="noopener noreferrer">Vercel AI Gateway documentation ↗</a></details><h2>${t('版本與依據','Version & evidence')}</h2><p>v0.6 · ${t('教師免費使用、繁體、簡體及英文介面、直接生成、複製與列印及 AI 接入。研究來源並不構成官方認證。','Free teacher access, Traditional Chinese, Simplified Chinese and English interfaces, direct generation, copying, printing and AI integration. Source reviews do not imply official endorsement.')}</p></article>`;}

function showSource(id){const s=sources.find(x=>x.id===id);if(!s)return;const d=s[lang];$('#source-content').innerHTML=`<p class="eyebrow">EEF / EVIDENCE NOTE</p><h2 id="source-title">${d.title}</h2><span class="tag orange">${d.strength}</span>${[[t('研究發現','Findings'),d.finding],[t('研究範圍','Scope'),d.scope],[t('局限','Limitations'),d.limit]].map(([k,v])=>`<h3>${k}</h3><p>${v}</p>`).join('')}<p class="source-citation">${t('來源更新','Source updated')}: ${s.updated}<br>${t('摘要核對','Summary reviewed')}: ${s.reviewed}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">${t('核對原始來源 ↗','Check the original source ↗')}</a>`;$('#source-dialog').setAttribute('aria-labelledby','source-title');$('#source-dialog').showModal();}
async function copyActivity(full=false){
 syncPlan();
 const lines=[plan.title,`${t('年級','Year group')}: ${stageLabel(draft,lang)} · ${draft.subject}`,`${t('時間','Duration')}: ${draft.minutes} ${t('分鐘','minutes')}`,`${t('學習目標','Goal')}: ${plan.goal||draft.goal}`];
 if(plan.knowledgePath?.length)lines.push(t('知識點銜接','Knowledge connections')+'\n'+plan.knowledgePath.join(' → '));if(plan.revisionNotes?.length)lines.push(plan.revisionNotes.join('\n'));for(const [index,step] of plan.steps.entries())lines.push(`${index+1}. ${step.title} (${step.minutes} ${t('分鐘','min')})\n${[step.concept,step.text,step.check,step.bridge].filter(Boolean).join('\n')}`);if(!full){lines.push(t('材料','Materials')+': '+(plan.materials||''),t('離堂檢查','Exit check')+': '+(plan.exitCheck||''));for(const [key,label]of evaluationLabels().filter(([key])=>['continueWhen','adjustWhen','tryDifferentWhen'].includes(key)))if(plan.evaluation?.[key])lines.push(label+': '+plan.evaluation[key]);try{await navigator.clipboard.writeText(lines.join('\n\n'));toast(t('已複製流程。','Flow copied.'));}catch{toast(t('未能複製，請使用列印。','Copy unavailable. Use print.'));}return;}
 for(const [label,value] of [[t('活動怎樣對應目標','Goal alignment'),plan.learningRationale],[t('開始前的檢查','Readiness check'),plan.prerequisiteCheck],[t('提問與句式','Teacher prompts'),plan.teacherPrompts],[t('學生任務','Pupil task'),plan.studentTask],[t('快速檢查','Quick check'),plan.exitCheck],[t('材料','Materials'),plan.materials],[t('支援安排','Support'),plan.support],[t('我的備註','My notes'),plan.teacherNote]])if(value)lines.push(`${label}\n${value}`);
 for(const [key,label]of evaluationLabels())if(plan.evaluation?.[key])lines.push(`${label}\n${plan.evaluation[key]}`);
 for(const note of plan.evidence||[]){const source=getPlanSources().find(item=>item.id===note.sourceId);lines.push(`${t('研究依據','Evidence')}: ${note.finding}\n${note.application?t('這次怎樣用','Classroom adaptation')+': '+note.application+'\n':''}${t('局限','Limit')}: ${note.limitation}${source?'\n'+source.url:''}`);}
 try{await navigator.clipboard.writeText(lines.join('\n\n'));toast(t('已複製活動，可貼到教案或文件。','Activity copied. Paste it into your lesson plan.'));}catch{toast(t('瀏覽器未能複製，請使用列印或手動選取內容。','Copying is unavailable. Print the activity or select the text manually.'));}
}

function exportRecords(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({product:'TeachWithWhy',version:4,teachingSettings,exported:new Date().toISOString(),records,presets},null,2)],{type:'application/json'}));a.href=url;a.download='teachwithwhy-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('備份下載已開始。','Backup download started.'));}
function validImport(r){
 const strings=a=>Array.isArray(a)&&a.length<=20&&a.every(x=>typeof x==='string');
 if(!r||typeof r.id!=='string'||r.id.length>100||typeof r.title!=='string'||!r.draft||!Object.hasOwn(levels.en,r.draft.level)||!Number.isInteger(r.draft.students)||r.draft.students<2||r.draft.students>60||!Number.isInteger(r.draft.minutes)||r.draft.minutes<5||r.draft.minutes>30||!strings(r.draft.constraints)||!['auto','think','joint','reason'].includes(r.draft.strategy)||!r.plan||typeof r.plan.title!=='string'||!Array.isArray(r.plan.steps)||!r.plan.steps.length||r.plan.steps.length>10||!r.plan.steps.every(s=>s&&typeof s.title==='string'&&typeof s.text==='string'&&Number.isInteger(s.minutes)&&s.minutes>0))return false;
 if(['learningRationale','prerequisiteCheck','teacherPrompts','studentTask','exitCheck','teacherNote'].some(k=>r.plan[k]!==undefined&&typeof r.plan[k]!=='string'))return false;
 if(r.plan.evaluation&&(!r.plan.evaluation||typeof r.plan.evaluation!=='object'||evaluationLabels().some(([key])=>typeof r.plan.evaluation[key]!=='string')))return false;
 if(r.plan.knowledgePath&&!strings(r.plan.knowledgePath))return false;if(r.plan.revisionNotes&&!strings(r.plan.revisionNotes))return false;if(r.plan.steps.some(s=>['concept','bridge','check'].some(k=>s[k]!==undefined&&typeof s[k]!=='string')))return false;if(r.draft.reuseContext&&(typeof r.draft.reuseContext.parentId!=='string'||typeof r.draft.reuseContext.title!=='string'||!Array.isArray(r.draft.reuseContext.steps)))return false;
 if(r.plan.observations&&!strings(r.plan.observations))return false;
 if(r.plan.cautions&&!strings(r.plan.cautions))return false;
 if(r.plan.evidence&&(!Array.isArray(r.plan.evidence)||r.plan.evidence.some(e=>!e||typeof e.sourceId!=='string'||typeof e.finding!=='string'||typeof e.limitation!=='string')))return false;
 if(r.plan.sources&&(!Array.isArray(r.plan.sources)||r.plan.sources.length>20||!r.plan.sources.every(s=>{try{const u=new URL(s.url);return u.protocol==='https:'&&!u.username&&!u.password;}catch{return false;}})))return false;
 if(r.reflection&&(!r.reflection.observation||typeof r.reflection.observation!=='string'))return false;
 if(r.favorite!==undefined&&typeof r.favorite!=='boolean')return false;
 if(r.draft.curriculum!==undefined&&!Object.hasOwn(curricula,r.draft.curriculum))return false;
 if(['curriculumNote','customPrompt','documentContext','documentName','textbook','classContext','knowledgePoints'].some(k=>r.draft[k]!==undefined&&typeof r.draft[k]!=='string'))return false;
 if(r.feedbackHistory&&(!Array.isArray(r.feedbackHistory)||r.feedbackHistory.length>200||r.feedbackHistory.some(x=>!x||typeof x.created!=='string'||!x.snapshot||typeof x.snapshot.observation!=='string'||(x.ai&&!['keep','adjust','uncertainty'].every(k=>strings(x.ai.result?.[k]))))))return false;
 if(r.reflectionAI&&!['keep','adjust','uncertainty'].every(k=>strings(r.reflectionAI.result?.[k])))return false;
 return true;
}
async function importRecords(file){if(!file)return;if(file.size>8000000){toast(t('備份檔案過大。','Backup file is too large.'));return;}try{const data=JSON.parse(await file.text());if(!['TeachWithWhy','Evidence to Classroom'].includes(data.product)||!Array.isArray(data.records)||data.records.length>200||!data.records.every(validImport))throw Error();const ids=new Set(records.map(r=>r.id)),newItems=data.records.filter(r=>!ids.has(r.id));const incomingPresets=data.presets||[];if(!Array.isArray(incomingPresets)||incomingPresets.length>30||!incomingPresets.every(validPreset))throw Error();const known=new Set(presets.map(p=>p.id));const nextPresets=[...presets,...incomingPresets.filter(p=>!known.has(p.id))];if(nextPresets.length>30)throw Error();const old=records,oldPresets=presets,oldSettings=teachingSettings;if(data.teachingSettings!==undefined&&(!Array.isArray(data.teachingSettings?.profiles)||data.teachingSettings.profiles.length>30||!data.teachingSettings.profiles.every(validProfile)))throw Error();teachingSettings=mergeSettings(teachingSettings,data.teachingSettings);records=[...newItems.map(normalizeRecord),...records];presets=nextPresets;if(persistWorkspace()){navigate('history');toast(t(`已匯入 ${newItems.length} 個新紀錄；相同編號保留現有版本。`,`Imported ${newItems.length} new records; existing IDs were kept.`));}else{records=old;presets=oldPresets;teachingSettings=oldSettings;}}catch{toast(t('備份格式不正確，沒有修改現有紀錄。','Invalid backup. Existing records were not changed.'));}}
function persistPresets(){try{localStorage.setItem('teachwithwhy-prompts-v1',JSON.stringify(presets));return true;}catch{toast(t('無法儲存提示，請先下載備份。','Prompt storage failed. Download a backup first.'));return false;}}
function persistWorkspace(){const keys=['teachwithwhy-records-v2','teachwithwhy-prompts-v1','teachwithwhy-teaching-settings-v1'];let previous;try{previous=keys.map(k=>localStorage.getItem(k));localStorage.setItem(keys[0],JSON.stringify(records));localStorage.setItem(keys[1],JSON.stringify(presets));localStorage.setItem(keys[2],JSON.stringify(teachingSettings));return true;}catch{if(previous)keys.forEach((key,i)=>{try{if(previous[i]===null)localStorage.removeItem(key);else localStorage.setItem(key,previous[i]);}catch{}});toast(t('瀏覽器空間不足，請先下載備份。','Browser storage is full. Download a backup first.'));return false;}}
function savePreset(){capture();const title=$('#preset-title')?.value.trim(),text=draft.customPrompt.trim();if(!title||!text){toast(t('請填寫提示內容及按鈕名稱。','Enter the prompt and a shortcut name.'));return;}if(presets.length>=30){toast(t('最多儲存 30 個提示，請先整理或下載備份。','Save up to 30 prompts. Organise them or download a backup first.'));return;}const previous=presets;presets=[...presets,{id:crypto.randomUUID(),title,text}];if(persistPresets()){presetEditor=false;presetTitle='';navigate('home',false);toast(t('已儲存為快捷提示，下次可直接點選。','Shortcut saved. Click it next time to reuse the prompt.'));}else presets=previous;}
const documentError=code=>({DOCX_ONLY:t('請選擇 .docx；舊 .doc 請先在 Word 另存為 .docx。','Choose .docx. Save legacy .doc as .docx in Word first.'),FILE_SIZE:t('請選擇不超過 5 MB 的 Word 檔案。','Choose a Word file of up to 5 MB.'),EMPTY_DOCUMENT:t('未找到正文文字；掃描圖片暫不支援，可直接貼上文字。','No body text found. Scanned images are not supported; paste the text instead.'),DOCUMENT_TOO_LONG:t('正文超過 20,000 字，請另存較短片段，或只貼上相關內容。','The body exceeds 20,000 characters. Save a shorter section or paste relevant text.'),DOCUMENT_TIMEOUT:t('檔案讀取逾時，請另存較簡單的 .docx，或貼上文字。','Reading timed out. Save a simpler .docx or paste the text.'),INVALID_DOCX:t('未能讀取此 Word 檔案。請確認不是加密檔案，並另存為一般 .docx，或貼上文字。','Could not read this document. Check that it is not encrypted; save a standard .docx or paste its text.')})[code]||errorText(code);
async function loadWord(file){if(!file||busy)return;capture();busy=true;updateStatus();try{const text=await readWord(file);documentImport={text,name:file.name,suggestion:null,notes:'',consent:false,error:'',attached:false};draft.documentContext='';draft.documentName='';toast(t('已讀取正文，請先核對，再交由 AI 解析。','Text extracted. Review it before AI analysis.'));}catch(e){documentImport.error=documentError(e.message);}busy=false;navigate('home',false);}
async function parseDocument(){capture();if(!documentImport.text.trim()){toast(t('請先選擇 Word 或貼上文字。','Choose a Word file or paste text first.'));return;}if(!documentImport.consent){toast(t('請先確認教案文字的 AI 處理選項。','Confirm consent to AI analysis of the document text.'));return;}if(!api.configured){toast(errorText('AI_NOT_CONFIGURED'));return;}const submitted=documentImport.text;busy=true;documentImport.error='';updateStatus();try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'parse',lang,consent:true,documentText:submitted}),signal:AbortSignal.timeout(100000)});const j=await r.json();if(!r.ok)throw Error(j.error||'NETWORK_ERROR');documentImport.suggestion=j.suggestion;documentImport.notes=j.notes;documentImport.analysedText=submitted;toast(t('解析完成，請確認後套用。','Analysis ready. Review it before applying.'));}catch(e){documentImport.error=documentError(e.message);}busy=false;navigate('home',false);}
function applyDocument(){capture();if(!documentImport.suggestion)return;if(documentImport.text!==documentImport.analysedText){toast(t('文字已修改，請重新解析，避免套用舊結果。','The text changed. Analyse it again before applying the old result.'));return;}for(const [key,value]of Object.entries(documentImport.suggestion))if(value!==null)draft[key]=value;if(documentImport.suggestion.subject)draft.customSubject='';draft.documentContext=documentImport.text;draft.documentName=documentImport.name;documentImport.attached=true;documentImport.suggestion=null;navigate('home',false);toast(t('已套用；請補充未提及的資料，再生成活動。','Applied. Complete missing context before generating.'));}
function bindForms(){const f=$('#class-form');if(f){let timer;f.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(document.querySelector('#class-form')===f)capture();},500);});f.addEventListener('change',()=>capture());}$('#teaching-profile')?.addEventListener('change',e=>{capture();const p=teachingSettings.profiles.find(p=>p.id===e.target.value);teachingSettings.lastProfileId=p?.id||'';if(p)Object.assign(draft,localizedSetup(p.setup));rememberSetup();navigate('home',false);});if(f)f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;capture();if(!draft.topic.trim()||!draft.goal.trim()){toast(errorText('INVALID_INPUT'));return;}if(!draft.consent){toast(errorText('CONSENT_REQUIRED'));return;}generate(draft.strategy);});const r=$('#reflection-form');if(r)r.addEventListener('submit',e=>{e.preventDefault();if(saveReflection()){toast(t('回顧已儲存。','Reflection saved.'));navigate('history');}});$('#word-file')?.addEventListener('change',e=>loadWord(e.target.files[0]));$('#curriculum')?.addEventListener('change',()=>{capture();draft.subject=getSubjects(draft.curriculum,draft.level,lang)[0];draft.customSubject='';rememberSetup();navigate('home',false);});$('#level')?.addEventListener('change',()=>{capture();navigate('home',false);});$('#class-form')?.querySelectorAll('[name=feedbackIds]').forEach(input=>input.addEventListener('change',()=>{if(document.querySelectorAll('[name=feedbackIds]:checked').length>3){input.checked=false;toast(t('最多選三份回顧。','Choose up to three reflections.'));}}));$('#import-file')?.addEventListener('change',e=>importRecords(e.target.files[0]));}
function switchLanguage(nextLanguage){
 if(!['zh','zh-CN','en'].includes(nextLanguage))return;
 const previousLang=lang,previousView=view,scrollY=window.scrollY;
 if($('#class-form'))capture();
 if(view==='plan')syncPlan();
 const reflectionForm=$('#reflection-form');
 const reflectionDraft=reflectionForm?Object.fromEntries(new FormData(reflectionForm)):null;
 const participationIndex=$('#participation')?.selectedIndex;
 lang=nextLanguage;en=lang==='en';
 names=translate_names();exampleProblems=translate_exampleProblems();exampleGoals=translate_exampleGoals();
 const subjectIndex=getSubjects(draft.curriculum,draft.level,previousLang).indexOf(draft.subject);
 if(subjectIndex>=0&&!draft.customSubject)draft.subject=getSubjects(draft.curriculum,draft.level,lang)[subjectIndex];
 try{localStorage.setItem('teachwithwhy-ui-language',lang);}catch{}
 shell();navigate(previousView,false);
 if(reflectionDraft){const form=$('#reflection-form');for(const [key,value]of Object.entries(reflectionDraft)){const input=form?.elements.namedItem(key);if(input&&key!=='participation')input.value=value;}if($('#participation'))$('#participation').selectedIndex=participationIndex;}
 window.scrollTo({top:scrollY,behavior:'instant'});
}
document.addEventListener('click',e=>{const el=e.target.closest('button,a[data-language]');if(!el)return;if(busy){e.preventDefault();toast(t('正在處理，請稍候。','Processing. Please wait.'));return;}if(el.dataset.nav){if($('#class-form'))capture();if(view==='plan')syncPlan();navigate(el.dataset.nav);return;}if(el.dataset.favorite){const previous=records;records=records.map(r=>r.id===el.dataset.favorite?{...r,favorite:!r.favorite}:r);if(persist())navigate('history',false);else records=previous;return;}if(el.dataset.preset){capture();const preset=presets.find(x=>x.id===el.dataset.preset);if(preset){draft.customPrompt=preset.text;navigate('home',false);$('#custom-prompt').focus();toast(t('已套用提示，可修改後再生成。','Prompt applied. Edit it before generating.'));}return;}if(el.dataset.removePreset){if(confirm(t('刪除這個自訂提示？請先下載備份。','Delete this saved prompt? Download a backup first.'))){const previous=presets;presets=presets.filter(x=>x.id!==el.dataset.removePreset);if(persistPresets()){capture();navigate('home',false);}else presets=previous;}return;}if(el.dataset.fill!==undefined){const i=Number(el.dataset.fill);$('#problem').value=exampleProblems[i];if(!$('#goal').value.trim())$('#goal').value=exampleGoals[i];$('#strategy').value=strategies[i].id;$('#problem').focus();return;}if(el.dataset.guideExample){const junior=el.dataset.guideExample==='junior';draft={...blank(),level:el.dataset.guideExample,subject:getSubjects('hk',junior?'junior':'upper',lang)[junior?3:0],students:junior?32:30,minutes:junior?15:12,topic:junior?t('比較兩個科學解釋','Comparing two scientific explanations'):t('故事人物的選擇','A character’s choices'),strategy:junior?'reason':'think',goal:junior?t('比較兩個解釋，指出各自依據及未知之處。','Compare two explanations, identify their evidence and note uncertainty.'):t('每人先提出想法，再用一個理由解釋人物的選擇。','Each pupil prepares an idea and a reason for a character’s choice.')};activeId=null;plan=null;navigate('create');return;}if(el.dataset.source){showSource(el.dataset.source);return;}if(el.dataset.ai){generate(el.dataset.ai);return;}if(el.dataset.sample){draft.strategy=el.dataset.sample;plan=samplePlan(draft,lang);activeId=null;navigate('plan');return;}if(el.dataset.open){open(el.dataset.open);return;}if(el.dataset.reuse){const r=records.find(r=>r.id===el.dataset.reuse);if(r){draft=reuseActivity(r);teachingSettings.lastProfileId='';documentImport={text:draft.documentContext||'',name:draft.documentName||'',suggestion:null,notes:'',consent:false,error:'',attached:Boolean(draft.documentContext)};plan=null;activeId=null;navigate('home');}return;}if(el.dataset.review){open(el.dataset.review,'reflect');return;}if(el.dataset.delete){if(confirm(t('刪除此活動及回顧？無法復原，建議先下載備份。','Delete this activity and reflection? This cannot be undone; download a backup first.'))){const prev=records;records=records.filter(r=>r.id!==el.dataset.delete);if(persist())navigate('history');else records=prev;}return;}switch(el.dataset.action){case'save-profile':saveTeachingProfile(false);break;case'update-profile':saveTeachingProfile(true);break;case'apply-plan':syncPlan();planEditing=false;navigate('plan',false);toast(t('已套用修改。','Edits applied.'));break;case'copy-full':copyActivity(true);break;case'print-full':printActivity(true);break;case'install-guide':if($('#class-form'))capture();if(view==='plan')syncPlan();navigate('guide');$('#install-guide').scrollIntoView({block:'start',behavior:'instant'});break;case'parse-document':parseDocument();break;case'apply-document':applyDocument();break;case'clear-document':capture();draft.documentContext='';draft.documentName='';documentImport={text:'',name:'',suggestion:null,notes:'',consent:false,error:''};navigate('home',false);break;case'toggle-preset':capture();presetEditor=!presetEditor;navigate('home',false);break;case'save-preset':savePreset();break;case'show-all':onlyFavorites=false;navigate('history',false);break;case'show-favorites':onlyFavorites=true;navigate('history',false);break;case'new':documentImport={text:'',name:'',suggestion:null,notes:'',consent:false,error:''};draft=blank();plan=null;activeId=null;navigate('home');break;case'sample-start':{capture();if(!draft.topic)draft.topic=t('故事人物的選擇','A character’s choices');if(!draft.problem)draft.problem=exampleProblems[0];if(!draft.goal)draft.goal=t('每位學生能參與活動，並用理由解釋自己的想法。','Each pupil participates and explains an idea with a reason.');plan=samplePlan(draft,lang);activeId=null;navigate('plan');break;}case'copy':copyActivity();break;case'save':save();break;case'reflect':if(save(true))navigate('reflect');break;case'reflect-ai':reflectAI();break;case'export':exportRecords();break;case'print':printActivity();break;case'refresh-status':checkStatus();break;}});
document.addEventListener('change',e=>{if(e.target.id==='ui-language'){if(busy){e.target.value=lang;return;}switchLanguage(e.target.value);}});
shell();try{const s=JSON.parse(sessionStorage.getItem('etc-language-state')||'null');if(s?.draft){draft=s.draft;plan=s.plan;activeId=s.activeId;view=Object.hasOwn(names,s.view)?s.view:'home';sessionStorage.removeItem('etc-language-state');}}catch{}
navigate(view,false);checkStatus();

function rememberSetup(){teachingSettings.lastSetup=teachingSetup(draft);try{localStorage.setItem('teachwithwhy-teaching-settings-v1',JSON.stringify(teachingSettings));}catch{toast(t('未能保留常用設定，請下載備份。','Could not save settings. Download a backup.'));}}
function profileView(){return `<section class="profile-panel"><label for="teaching-profile">${t('常用班級','Saved teaching setups')}</label><select id="teaching-profile"><option value="">${t('最近使用的設定／未命名','Recent settings / unnamed')}</option>${teachingSettings.profiles.map(p=>`<option value="${esc(p.id)}" ${teachingSettings.lastProfileId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><details><summary>${t('儲存或更新常用班級','Save or update a setup')}</summary><label for="profile-name">${t('名稱（例如：五甲數學）','Name (for example: P5A Maths)')}</label><input id="profile-name" maxlength="60" value="${esc(profileName)}"><div class="output-actions">${b(t('另存常用班級','Save new setup'),'type="button" data-action="save-profile"','secondary')}${teachingSettings.lastProfileId?b(t('更新所選班級','Update selected setup'),'type="button" data-action="update-profile"','secondary'):''}</div><p class="subtext">${t('只儲存班級、教材、時間及資源等常用設定；不會儲存本課題目、目標、Word 文字或同意選項。修改設定後，可按更新保留到所選班級。','Only class, textbook, time and resource settings are saved. Lesson topic, goal, Word text and consent are excluded. Update explicitly to change a named setup.')}</p></details></section>`;}
function saveTeachingProfile(update){capture();const name=$('#profile-name')?.value.trim(),current=teachingSettings.profiles.find(p=>p.id===teachingSettings.lastProfileId);if(!update&&!name){toast(t('請填寫常用班級名稱。','Enter a setup name.'));return;}if(!update&&teachingSettings.profiles.length>=30){toast(t('最多保留 30 個常用班級。','Save up to 30 setups.'));return;}const previous=structuredClone(teachingSettings);const p={id:update&&current?current.id:crypto.randomUUID(),name:name||(current?.name||''),setup:teachingSetup(draft)};teachingSettings.profiles=[...teachingSettings.profiles.filter(x=>x.id!==p.id),p];teachingSettings.lastProfileId=p.id;if(persistWorkspace()){profileName='';navigate('home',false);toast(t('已儲存常用設定。','Teaching setup saved.'));}else teachingSettings=previous;}
function printActivity(full=false){syncPlan();document.querySelectorAll('[data-step],[data-extra],[data-evaluation],[data-stage-key]').forEach(x=>{if(x.nextElementSibling?.classList.contains('print-value'))x.nextElementSibling.textContent=x.value;});if($('#teacher-note')?.nextElementSibling)$('#teacher-note').nextElementSibling.textContent=plan.teacherNote;const details=[...document.querySelectorAll('.plan-details,.evidence-details')],states=details.map(d=>d.open);document.body.classList.toggle('print-full',full);details.forEach(d=>d.open=full);const restore=()=>{document.body.classList.remove('print-full');details.forEach((d,i)=>d.open=states[i]);};window.addEventListener('afterprint',restore,{once:true});window.print();restore();}

function workflowGuide(){return `<section class="about-prose workflow-guide"><h2>${t('新版快速使用：少填重複資料，直接看流程','Quick start: less repetition, a usable flow first')}</h2><ol><li>${t('第一次設定班級、教材／版本、人數及時間，可命名儲存。下次會保留最近設定；切換常用班級只改常用資料，不會覆蓋本課目標。更新已命名班級須按「更新所選班級」。教材名稱不代表 AI 能讀取整本書。','Set class, textbook/edition, pupils and time, then optionally save a named setup. Recent settings are remembered. Switching a setup keeps the current lesson goal. Update a named setup explicitly. A textbook name does not give AI access to the whole book.')}</li><li>${t('填本課課題及目標，可補充要串連的知識點、關鍵詞及學生困難。原有欄位在可展開的設定中保留。每次仍須確認 AI 處理同意。','Enter the topic and goal; optionally add knowledge points, keywords and lesson-specific needs. Original fields remain in expandable settings. Consent is required for each new activity.')}</li><li>${t('生成後先看知識點銜接、活動環節、任務及學習檢查。提問示例與完整依據在詳情內；修改後按「套用修改」。預設複製／列印流程版，完整版本在詳情內另選。舊活動保留原有流程，不會補寫成新的 AI 結果。','View knowledge connections, stages, tasks and checks first. Optional questions and full notes are in details. Apply edits to refresh the flow. Copy/print defaults to the flow; full versions are inside details. Older saved activities keep their original content.')}</li><li>${t('歷史頁按「沿用並改進」會另建新活動，保留原稿。若原活動有回顧，會預選最新一份，可取消或改選；生成前會送出所選回顧及原流程摘要。新結果會列明具體改動，並不表示已驗證成效。','Reuse & improve creates a new activity without overwriting the original. Its latest reflection is preselected if present; deselect or change it before generating. Only the selected feedback and prior flow summary are included. The result lists changes without claiming proven improvement.')}</li></ol><p>${t('常用班級、收藏、提示及回顧只存於此瀏覽器，備份會一併保存；不會自動同步或訓練模型。','Setups, favorites, prompts and reflections are browser-local and included in backups; there is no automatic sync or model training.')}</p></section>`;}

function localizedSetup(setup){const out=structuredClone(setup||{});if(out.subject&&!out.customSubject){for(const language of ['zh','zh-CN','en']){const index=getSubjects(out.curriculum||'hk',out.level||'upper',language).indexOf(out.subject);if(index>=0){out.subject=getSubjects(out.curriculum||'hk',out.level||'upper',lang)[index];break;}}}return out;}
